    /**
     * Performs an INSERT on the database, given a EnviadaUsuario or Criteria object.
     *
     * @param      mixed $values Criteria or EnviadaUsuario object containing data that is used to create the INSERT statement.
     * @param      PropelPDO $con the PropelPDO connection to use
     * @return mixed           The new primary key.
     * @throws PropelException Any exceptions caught during processing will be
     *		 rethrown wrapped into a PropelException.
     */
    public static function doInsert($values, PropelPDO $con = null)
    {
        if ($con === null) {
            $con = Propel::getConnection(EnviadaUsuarioPeer::DATABASE_NAME, Propel::CONNECTION_WRITE);
        }

        if ($values instanceof Criteria) {
            $criteria = clone $values; // rename for clarity
        } else {
            $criteria = $values->buildCriteria(); // build Criteria from EnviadaUsuario object
        }

        if ($criteria->containsKey(EnviadaUsuarioPeer::ENVIADAUSUARIO_ID) && $criteria->keyContainsValue(EnviadaUsuarioPeer::ENVIADAUSUARIO_ID) ) {
            throw new PropelException('Cannot insert a value for auto-increment primary key ('.EnviadaUsuarioPeer::ENVIADAUSUARIO_ID.')');
        }

        // remove pkey col since this table uses auto-increment and passing a null value for it is not valid
        $criteria->remove(EnviadaUsuarioPeer::ENVIADAUSUARIO_ID);


        // Set the correct dbName
        $criteria->setDbName(EnviadaUsuarioPeer::DATABASE_NAME);

        try {
            // use transaction because $criteria could contain info
            // for more than one table (I guess, conceivably)
            $con->beginTransaction();
            $pk = BasePeer::doInsert($criteria, $con);
            $con->commit();
        } catch (Exception $e) {
            $con->rollBack();
            throw $e;
        }

        return $pk;
    }

