            $comparison = $criteria->getComparison(EnviadaUsuarioPeer::ENVIADAUSUARIO_ID);
            $value = $criteria->remove(EnviadaUsuarioPeer::ENVIADAUSUARIO_ID);
            if ($value) {
                $selectCriteria->add(EnviadaUsuarioPeer::ENVIADAUSUARIO_ID, $value, $comparison);
            } else {
                $selectCriteria->setPrimaryTableName(EnviadaUsuarioPeer::TABLE_NAME);
            }

        } else { // $values is EnviadaUsuario object
            $criteria = $values->buildCriteria(); // gets full criteria
            $selectCriteria = $values->buildPkeyCriteria(); // gets criteria w/ primary key(s)
        }

        // set the correct dbName
        $criteria->setDbName(EnviadaUsuarioPeer::DATABASE_NAME);

        return BasePeer::doUpdate($selectCriteria, $criteria, $con);
